import{_ as e,o as i,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-11：柏拉图式脑桥假说","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-09-11-platonic-brain.md","filePath":"topics/neuroscience/science-daily-2026-09-11-platonic-brain.md"}'),n={name:"topics/neuroscience/science-daily-2026-09-11-platonic-brain.md"};function r(l,a,c,s,d,u){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="科学日报-·-2026-09-11-柏拉图式脑桥假说" tabindex="-1">科学日报 · 2026-09-11：柏拉图式脑桥假说 <a class="header-anchor" href="#科学日报-·-2026-09-11-柏拉图式脑桥假说" aria-label="Permalink to &quot;科学日报 · 2026-09-11：柏拉图式脑桥假说&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-11.md</code> ｜ arXiv:2609.10947 ｜ 另见 ai-brain/index.md</p></blockquote><h2 id="核心命题" tabindex="-1">核心命题 <a class="header-anchor" href="#核心命题" aria-label="Permalink to &quot;核心命题&quot;">​</a></h2><p>全能模型（omni multimodal：视频/音频/文本联合，类脑处理）会聚到<strong>类脑表征</strong>，且对应是<strong>双向</strong>的：</p><ul><li><strong>模型→脑</strong>：7 个 omni 模型的「类脑程度」跨被试稳定；其内部隐状态的编码模型在 Algonauts 2025 分布外排行榜上排第一 → 最强多模态模型确实长出了类脑的内部结构。</li><li><strong>脑→模型</strong>：Brain-MoE 给 7 个皮层网络各配一个脑预训练专家 → 15 个模型-基准组合平均保留精度 +6.42 个百分点 → 「人脑网络作为架构先验」有直接、稳定的收益。</li></ul><h2 id="与既有神经科学知识的关系" tabindex="-1">与既有神经科学知识的关系 <a class="header-anchor" href="#与既有神经科学知识的关系" aria-label="Permalink to &quot;与既有神经科学知识的关系&quot;">​</a></h2><ul><li>与此前「呼吸三通路」「scanpath 理论」共同印证：<strong>大脑结构信息能作为可迁移的归纳偏置</strong>，而不只是神经评估的靶子。</li><li>「脑作为 architectural prior」路线 = 「以脑为外在范式做模型设计」，与 AI 外脑「以人类知识组织方式为范本」同源——脑结构、知识结构、模型结构三者在此汇流。</li></ul><h2 id="开放问题" tabindex="-1">开放问题 <a class="header-anchor" href="#开放问题" aria-label="Permalink to &quot;开放问题&quot;">​</a></h2><ul><li>脑-MoE 的「专家→皮层网络」映射是否真的对应认知功能分区（默认网络/注意力网络…）？映射的因果性仍待验证。</li><li>双向对应是否只在「生态位接近人类感知」的 omni 任务上成立？</li></ul>',9)])])}const _=e(n,[["render",r]]);export{p as __pageData,_ as default};
